import{_ as a,o as e,c as t,a2 as s}from"./chunks/framework.D_M-uDGM.js";const d=JSON.parse('{"title":"Magic variant: asset requests","description":"","frontmatter":{},"headers":[],"relativePath":"guide/magic-assets.md","filePath":"guide/magic-assets.md"}'),o={name:"guide/magic-assets.md"};function i(r,n,h,l,c,g){return e(),t("div",null,[...n[0]||(n[0]=[s(`<h1 id="magic-variant-asset-requests" tabindex="-1">Magic variant: asset requests <a class="header-anchor" href="#magic-variant-asset-requests" aria-label="Permalink to &quot;Magic variant: asset requests&quot;">​</a></h1><p>Bản game phụ thứ ba, <strong>Magic</strong> (sẽ ở <code>/magic/</code>, nút <strong>Play Magic</strong> ở trang chủ). Cùng level và luật chơi như bản thường; khác ở khung cảnh: level là <strong>dấu niêm phong (seal) trên một cánh cửa</strong>.</p><h2 id="cach-choi" tabindex="-1">Cách chơi <a class="header-anchor" href="#cach-choi" aria-label="Permalink to &quot;Cách chơi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lúc</th><th>Điều xảy ra</th></tr></thead><tbody><tr><td>Vào level</td><td>Hai cánh cửa <strong>sập vào từ hai bên</strong>, khép lại ở giữa màn hình.</td></tr><tr><td>Ngay sau khi cửa khép</td><td>Hai bóng của mỗi cặp <strong>cùng nằm ở một đầu dây</strong>; một bóng <strong>chạy theo dây tới đầu còn lại</strong>, nên hai bóng rời xa nhau và về đúng vị trí bắt đầu chơi.</td></tr><tr><td>Khi chơi</td><td>Như bản thường, trên mặt cửa (màu nền của theme). Cửa đứng yên trên màn hình; pinch zoom chỉ phóng to level (dây và bóng).</td></tr><tr><td>Gỡ hết bóng</td><td>Level <strong>trở về độ zoom bình thường và canh giữa lại</strong>, khe cửa hiện ra và <strong>ánh sáng lọt qua khe</strong>, rồi hai cánh cửa <strong>mở ra hai bên</strong>, ánh sáng phía sau tràn ra, rồi hiện <strong>Well Done</strong>.</td></tr><tr><td>Bấm Next</td><td>Cửa <strong>sập lại</strong>, level sau bắt đầu (bóng lại chạy ra).</td></tr></tbody></table><p>Bóng giữ như bản thường, trừ khi có ảnh <code>orb.png</code>.</p><p>Bóng, map sáng lúc phá seal, chuyển động cửa, rung khi cửa sập, thời điểm và độ mạnh của ánh sáng, giọt nước, tia nổ và màn Well Done đều làm bằng code. Ảnh chỉ cần cho cửa, phía sau cửa và ánh sáng.</p><h2 id="quy-cach-chung" tabindex="-1">Quy cách chung <a class="header-anchor" href="#quy-cach-chung" aria-label="Permalink to &quot;Quy cách chung&quot;">​</a></h2><ul><li><strong>Định dạng:</strong> PNG, sRGB. Cỡ ghi ở từng ảnh; ra cỡ to hơn cùng tỉ lệ cũng được, mình sẽ thu nhỏ.</li><li><strong>Ảnh toàn màn hình:</strong> <strong>1170 × 2532</strong> (tỉ lệ dọc 6:13; Midjourney: <code>--ar 6:13</code>). Nếu công cụ không ra đúng tỉ lệ, chọn khung dọc cao nhất có thể (9:16) và để phần trên, dưới là viền cửa đơn giản, mình sẽ nối thêm.</li><li><strong>Vùng bị che</strong> (trên ảnh 1170 × 2532): <strong>345 px trên cùng</strong> nằm dưới thanh HUD, <strong>315 px dưới cùng</strong> nằm dưới thanh booster.</li><li><strong>Vùng seal (giữa cửa) phải &quot;yên&quot;:</strong> phẳng, ít chi tiết, tương phản thấp, tông trung bình đến tối, để dây và bóng nhiều màu nổi rõ. (Hiện game đổi mặt cửa sang màu nền của theme, chỉ giữ vân của ảnh.)</li><li><strong>Nền:</strong> công cụ tạo ảnh thường không ra được nền trong suốt, nên các ảnh ánh sáng xin <strong>nền đen tuyệt đối</strong> (mình dùng chế độ cộng sáng, phần đen tự biến mất), còn <code>orb.png</code> xin <strong>nền xanh lá thuần #00FF00</strong> (mình tách nền).</li><li><strong>Không có chữ, logo, watermark</strong>; không vẽ bóng, dây hay hình level lên cửa.</li><li><strong>Cùng phong cách:</strong> dán đoạn <em>Style</em> dưới đây vào đầu mỗi prompt (đổi nếu bạn muốn phong cách khác).</li></ul><h2 id="prompts" tabindex="-1">Prompts <a class="header-anchor" href="#prompts" aria-label="Permalink to &quot;Prompts&quot;">​</a></h2><h3 id="style-dan-vao-đau-moi-prompt" tabindex="-1">Style (dán vào đầu mỗi prompt) <a class="header-anchor" href="#style-dan-vao-đau-moi-prompt" aria-label="Permalink to &quot;Style (dán vào đầu mỗi prompt)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Style: polished mobile casual puzzle game art, stylized fantasy, hand-painted look with clean readable shapes, soft global light from the top left, rich materials but low visual noise, cohesive palette of deep slate blue, muted violet and antique gold accents.</span></span></code></pre></div><h3 id="_1-door-png-bat-buoc-canh-cua-đong" tabindex="-1">1. <code>door.png</code> (bắt buộc): cánh cửa đóng <a class="header-anchor" href="#_1-door-png-bat-buoc-canh-cua-đong" aria-label="Permalink to &quot;1. \`door.png\` (bắt buộc): cánh cửa đóng&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Style]</span></span>
<span class="line"><span>A closed ancient enchanted double door, seen perfectly straight-on in orthographic front view, filling the entire portrait frame edge to edge, with no walls, floor, ceiling or sky visible around it.</span></span>
<span class="line"><span>The door is split into two equal leaves by a single thin, perfectly straight, perfectly vertical seam running from the very top to the very bottom exactly through the horizontal centre of the image. The seam is a crisp dark hairline with a faint warm glow, nothing crosses it: no handles, no lock, no bar, no emblem, no ornament overlapping the centre line.</span></span>
<span class="line"><span>The two leaves are mirror-symmetrical.</span></span>
<span class="line"><span>Ornamentation only on the outer zones: an ornate frame of carved arcane runes, antique gold filigree and small rivets along the left and right outer edges; a decorative arch band across the top 15 percent of the image and a heavy decorated base band across the bottom 12 percent.</span></span>
<span class="line"><span>The large central area of both leaves (from about 15 percent to 88 percent of the height, and from 8 percent to 92 percent of the width) is a calm, smooth, flat panel of dark slate-blue enchanted stone with a very subtle fine grain, even matte surface, low contrast, no engravings, no cracks, no patterns, no symbols, so that coloured objects placed on it later remain clearly readable.</span></span>
<span class="line"><span>Even, soft lighting across the whole door, no strong shadows, no vignette in the centre, no light rays.</span></span>
<span class="line"><span>Portrait aspect ratio 6:13, 1170 x 2532 pixels, high resolution, sharp.</span></span>
<span class="line"><span>Negative: text, letters, logo, watermark, people, perspective, tilted view, doorknob, keyhole, chains, padlock, central emblem, circles in the centre, busy patterns in the middle, cracks, light beams.</span></span></code></pre></div><h3 id="_2-backdrop-png-bat-buoc-phia-sau-cua" tabindex="-1">2. <code>backdrop.png</code> (bắt buộc): phía sau cửa <a class="header-anchor" href="#_2-backdrop-png-bat-buoc-phia-sau-cua" aria-label="Permalink to &quot;2. \`backdrop.png\` (bắt buộc): phía sau cửa&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Style]</span></span>
<span class="line"><span>The view behind a magic door that has just opened: a radiant enchanted treasure sanctum, seen straight-on, filling the entire portrait frame.</span></span>
<span class="line"><span>The brightest point is in the exact centre of the image: an intense warm white-gold glow, as if a portal of pure light, with soft god rays radiating outwards.</span></span>
<span class="line"><span>Towards the edges the scene fades into deep violet and slate-blue shadows with faint silhouettes of magical shelves, arches and floating glowing particles and sparkles; all detail stays soft and slightly blurred so it reads as background.</span></span>
<span class="line"><span>The upper and lower thirds should be calm and dimmer, because white text and buttons will be placed over them.</span></span>
<span class="line"><span>Portrait aspect ratio 6:13, 1170 x 2532 pixels, high resolution.</span></span>
<span class="line"><span>Negative: text, letters, logo, watermark, people, characters, creatures, doors, hard edges in the centre, overexposed full-white frame.</span></span></code></pre></div><h3 id="_3-light-ray-png-nen-co-tia-sang-lot-qua-khe" tabindex="-1">3. <code>light-ray.png</code> (nên có): tia sáng lọt qua khe <a class="header-anchor" href="#_3-light-ray-png-nen-co-tia-sang-lot-qua-khe" aria-label="Permalink to &quot;3. \`light-ray.png\` (nên có): tia sáng lọt qua khe&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A single tall vertical beam of magical light leaking through a narrow crack, isolated on a pure solid black background (#000000).</span></span>
<span class="line"><span>The beam runs the full height of the image, centred horizontally: an extremely thin, intensely bright white core with a warm gold tint, surrounded by a soft glow that fades smoothly to black within about a third of the image width on each side.</span></span>
<span class="line"><span>A few very fine, faint horizontal light streaks and tiny glittering specks escape sideways from the core at random heights.</span></span>
<span class="line"><span>Nothing else in the image: no door, no walls, no texture, no noise in the black.</span></span>
<span class="line"><span>Tall narrow image, 256 x 2532 pixels (or any tall portrait size with the beam centred).</span></span>
<span class="line"><span>Negative: text, watermark, background texture, gradient in the black area, coloured background, frame.</span></span></code></pre></div><h3 id="_4-light-burst-png-nen-co-luong-sang-khi-cua-mo" tabindex="-1">4. <code>light-burst.png</code> (nên có): luồng sáng khi cửa mở <a class="header-anchor" href="#_4-light-burst-png-nen-co-luong-sang-khi-cua-mo" aria-label="Permalink to &quot;4. \`light-burst.png\` (nên có): luồng sáng khi cửa mở&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A radial burst of magical god rays exploding from the exact centre of the image, isolated on a pure solid black background (#000000).</span></span>
<span class="line"><span>Bright white-gold core, around 30 long tapering rays of varying length and width spreading in all directions, a soft circular bloom around the centre, a few tiny sparkles along the rays; the rays fade completely to black before reaching the image edges.</span></span>
<span class="line"><span>Perfectly centred, square, 1024 x 1024 pixels.</span></span>
<span class="line"><span>Negative: text, watermark, any objects, background texture, coloured background, hard edges, rays cut off by the image border.</span></span></code></pre></div><h3 id="_5-sparkle-png-nen-co-hat-lap-lanh" tabindex="-1">5. <code>sparkle.png</code> (nên có): hạt lấp lánh <a class="header-anchor" href="#_5-sparkle-png-nen-co-hat-lap-lanh" aria-label="Permalink to &quot;5. \`sparkle.png\` (nên có): hạt lấp lánh&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A single magical sparkle for a game particle effect, isolated on a pure solid black background (#000000).</span></span>
<span class="line"><span>A pure white four-pointed star with long thin pointed rays (vertical and horizontal rays longer than the diagonals), a small bright round core, and a soft round white glow around the core.</span></span>
<span class="line"><span>Completely white and neutral, no colour tint.</span></span>
<span class="line"><span>Centred, small margin around it, nothing touching the edges, square, 128 x 128 pixels (or larger square).</span></span>
<span class="line"><span>Negative: text, watermark, colour, multiple stars, background texture.</span></span></code></pre></div><h3 id="_6-orb-png-tuy-chon-chi-khi-muon-đoi-bong-qua-cau-phep" tabindex="-1">6. <code>orb.png</code> (tùy chọn, chỉ khi muốn đổi bóng): quả cầu phép <a class="header-anchor" href="#_6-orb-png-tuy-chon-chi-khi-muon-đoi-bong-qua-cau-phep" aria-label="Permalink to &quot;6. \`orb.png\` (tùy chọn, chỉ khi muốn đổi bóng): quả cầu phép&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Style]</span></span>
<span class="line"><span>A single glossy magical glass orb, game sprite, isolated on a pure flat chroma-key green background (#00FF00).</span></span>
<span class="line"><span>The orb is neutral medium grey (no colour tint, so it can be recoloured in code), perfectly round, seen straight-on, with a soft inner glow in the centre, a darker rim around its edge, a large soft highlight and a small sharp white specular spot at the top left, and a faint bounce light at the bottom right.</span></span>
<span class="line"><span>No shadow on the background, no reflection of the background colour on the orb.</span></span>
<span class="line"><span>Centred, filling about 85 percent of the image, square, 256 x 256 pixels (or larger square).</span></span>
<span class="line"><span>Negative: text, watermark, colour tint, green reflections, drop shadow, base, stand, multiple orbs.</span></span></code></pre></div><h2 id="khong-can-anh" tabindex="-1">Không cần ảnh <a class="header-anchor" href="#khong-can-anh" aria-label="Permalink to &quot;Không cần ảnh&quot;">​</a></h2><p>Map sáng lúc phá seal (vẽ bằng code theo dây của level), bóng (khi không có <code>orb.png</code>), chuyển động cửa, rung khi cửa sập, thời điểm và độ mạnh của ánh sáng, giọt nước và tia nổ, màn Well Done.</p><h2 id="gui-anh" tabindex="-1">Gửi ảnh <a class="header-anchor" href="#gui-anh" aria-label="Permalink to &quot;Gửi ảnh&quot;">​</a></h2><ol><li>Bỏ ảnh gốc vào <code>art/magic/</code>, đặt đúng tên file như trên (ghi đè để thay ảnh).</li><li>Chạy <code>npm run art:magic</code>: tạo bản cỡ game trong <code>src/assets/magic/</code> (cửa và nền 780 × 1688, ảnh ánh sáng thành JPEG, <code>orb.png</code> thu về 256 × 256). Game chỉ đọc thư mục này, nên phải chạy lại lệnh này mỗi khi đổi ảnh gốc.</li><li>Tải lại trang dev (<code>?mode=magic</code>). Ảnh nào chưa có thì game dùng ảnh tạm vẽ bằng code (riêng <code>orb</code>: không có thì bóng như bản thường).</li></ol><p>Game tự xử lý thêm khi tải:</p><ul><li><code>door.png</code>: chỉ lấy mặt phẳng bên trong khung vàng (x 58–722 trên ảnh 780 px), che khe vẽ sẵn ở giữa (khe chỉ hiện khi cửa sắp mở), rồi đổi sang màu nền của theme, chỉ giữ vân của ảnh. <code>door-light.png</code> (tùy chọn) thay <code>door.png</code> làm vân cho theme sáng.</li><li><code>orb.png</code>: tách nền xanh, rồi tô từng màu của bảng màu (xám trung bình thành màu đó, xám tối thành tối hơn, xám sáng thành trắng).</li><li><code>backdrop.png</code>: vừa khít màn hình game (cả ảnh, không cắt).</li></ul>`,29)])])}const u=a(o,[["render",i]]);export{d as __pageData,u as default};
